import { action, add, baseState, documentationFields, sbarElements, score, set } from "./authoring";
import type { ClinicalScenarioInput } from "./schema";

// ─────────────────────────────────────────────────────────────────────────────
// Extended scenario library.
//
// Each case here was chosen because its expert route is unambiguous AND
// order-sensitive — the thing the best-practice sequence grader actually
// measures. A scenario where any reasonable order passes teaches nothing.
//
// Every case carries:
//   * distractors that target a real, documented misconception (not filler),
//   * at least one branch where the patient's trajectory changes what is correct,
//   * delayed effects, so "did it work?" requires reassessment rather than faith,
//   * failure conditions that fire on unsafe patterns rather than single slips,
//   * context-aware provider replies, so calling without data gets you questions.
//
// ⚠ All ship as status "clinical-review" / clinicalReviewerStatus "needs-review".
// They are authored against current guidelines but have NOT been signed off by a
// second clinician. They must stay admin-gated until they are reviewed.
// ─────────────────────────────────────────────────────────────────────────────

