      "Confusion and hypothermia are sepsis in an older adult; fever may never appear",
      "Family reports of a change from baseline are clinical data",
      "Cultures before antibiotics, but never let cultures delay the dose",
      "A lactate of 4 or above mandates 30 mL/kg even with an acceptable blood pressure",
      "Escalate before hypotension declares, not after",
