    overview: "Two things make this case. The first is that the cheapest intervention is the first one: he is at 12 degrees with a collar against his jugulars, and fixing that lowers the pressure before any drug. The second is the Cushing response — a systolic of 186 with a rate of 52 looks like hypertension that needs treating, and treating it collapses cerebral perfusion pressure to 33 and blows the pupil. The trigger detail matters too: the surge followed suctioning, which is why care is pre-medicated and clustered.",
    untreatedTrajectory: "Sustained intracranial hypertension progresses to uncal herniation with a fixed dilated pupil, extensor posturing, brainstem compression, and death. Hyperosmolar therapy and positioning are temporising; an enlarging haematoma needs evacuation.",
